/** host/policyApplied (#998): a machine kept this version of the policy. */
export interface PolicyApplied {
  version: number;
}

/**
 * Each person's budget per UTC day and per agent (#998, FR-016): a ceiling over their own
 * CostLimits. Money is US dollars.
 */
export interface PolicyBudgets {
  daily?: number;
  dailyTokens?: number;
  perAgent?: number;
  perAgentTokens?: number;
  /**
   * Runtime ids that may run under a budget though their turns report neither a cost nor tokens.
   */
  allowUnmetered: string[];
  /** An admin's raises, each for one person and one UTC day. */
  raises: BudgetRaise[];
}

/**
 * The variable names a person's own pass-through list may name (#998, FR-011a), * at the end
 * allowed.
 */
export interface PolicyEnvironment {
  passThrough: string[];
}

/** The ceiling over each folder's helper limits (#998, #64). */
export interface PolicyHelpers {
  mostRunning?: number;
  mostNotArchived?: number;
}

/**
 * policy/get and policy/set (#998): the whole policy with its store tag, for an admin. No policy
 * and no rev when none was ever set. machines is each machine's applied version, by host id.
 */
export interface PolicyKept {
  policy?: OrgPolicy;
  rev?: string;
  machines?: Record<string, number>;
}

/**
 * The marketplaces a policy allows (#998), by the ids #687 gives them, and whether an MCP server
 * added by hand is allowed.
 */
export interface PolicyMarketplaces {
  allowed: string[];
  customServers: "allow" | "refuse";
}

/** The notices a policy decides for every member (#999, FR-008). */
export interface PolicyNotices {
  /**
   * Google's terms notice for Antigravity: show (as absent), accepted (the organisation reviewed
   * them; no notice), refuse (Antigravity is refused).
   */
  antigravityTerms?: "show" | "accepted" | "refuse";
}

/** policy/raise (#998): an admin raises a person's budget for today (UTC). */
export interface PolicyRaiseRequest {
  user: string;
  daily?: number;
  dailyTokens?: number;
  request?: string;
}

/** A way a runtime reaches the model (#999): the person's own sign-in, an org key, or a gateway. */
export type PolicyReach =
  | "signIn"
  | "orgKey"
  | "gateway";

/**
 * The data of a policyRefused error (#998, FR-010): why, the rule, and the words for the client.
 */
export interface PolicyRefusal {
  reason: "policy" | "budget" | "stopAll" | "noPolicy" | "mustJoin" | "update";
  rule?: string;
  words: string;
  until?: WireDate;
}

/** One allowed runtime in a policy (#998). */
export interface PolicyRuntimeRule {
  /**
   * The model ids allowed, with * at the end allowed (claude-sonnet-*). Absent allows every model.
   */
  models?: string[];
  /**
   * The ways this runtime may reach the model (#999). Absent: every way. [orgKey, gateway] is the
   * org path only.
   */
  reach?: PolicyReach[];
}

/**
 * policy/set (#998): the rules, and the rev the admin read. No rev when there was no policy.
 * Refused changedElsewhere when another admin saved first.
 */
export interface PolicySet {
  policy: OrgPolicy;
  rev?: string;
}

/** The mark on a choice a policy refuses or caps (#998, FR-010). */
export interface PolicySetBy {
  by: "organisation";
  rule: string;
  words: string;
}

/**
 * The control key's signature of a policy (#998, FR-004), kept at v1/policy.sig: ECDSA P-256 with
 * SHA-256 (es256), over the policy's canonical JSON (keys sorted, no spaces). sig is the 64 bytes r
 * then s.
 */
export interface PolicySignature {
  version: number;
  /** The first 8 bytes of the SHA-256 of the control key's X9.63 public key, base64url. */
  keyID: string;
  alg: "es256";
  sig: Base64;
}

/**
 * daemon/policyState and daemon/policyStateChanged (#998, T027): the organisation's policy as this
 * machine follows it, so a client on the direct path draws the strip and the Policy pane. No
 * version when this machine has no policy.
 */
export interface PolicyState {
  version?: number;
  /** The rules in force here, with only this machine's person's raises. */
  policy?: OrgPolicy;
  /** The kill switch is on: this machine stops its turns and starts no work. */
  stopAll: boolean;
  /**
   * This machine had a policy from its organisation and has none it can trust now (missing, or it
   * fails the signature check). It starts no work until it gets one.
   */
  noPolicy: boolean;
  /** The capabilities the policy requires that this machine lacks (FR-014). It starts no work. */
  update?: string[];
  /** Why this machine starts no work now, when it starts none. */
  refusal?: PolicyRefusal;
}

/** The kill switch (#998, FR-015): while on, every machine stops its turns and starts no work. */
export interface PolicyStopAll {
  on: boolean;
  by: AuditActor;
  at: WireDate;
  note?: string;
}

/** policy/stopAll (#998): the kill switch on or off, with an optional note. */
export interface PolicyStopAllRequest {
  on: boolean;
  note?: string;
}

/**
 * policy/mine and control/policyChanged (#998): the policy in force, for any person, with only
 * their own budget raises. No policy when none was ever set.
 */
export interface PolicyView {
  policy?: OrgPolicy;
}

export interface PresenceReport {
  watching?: UUID;
  active: boolean;
  mayNotify?: boolean;
  showing?: UUID;
  alsoShowing?: UUID[];
}

export interface PreviewFile {
  path: string;
  bytes: number;
  runnable: boolean;
  via: string;
}

export type PreviewProblem =
  | { noSkillFile: Record<string, never> }
  | { notFoundInRepo: Record<string, never> }
  | { tooLarge: { bytes: number; files: number } }
  | { skipped: { _0: string[] } };

export interface PrewarmRequest {
  agentID: UUID;
  why: PrewarmRequestWhy;
}

export type PrewarmRequestWhy =
  | "opened"
  | "typing";

/**
 * A project (#2317): what people work on, the record that folders join. folders is what the
 * machines last reported.
 */
export interface Project {
  id: string;
  name: string;
  owner: string;
  folders: ProjectFolder[];
  /** The caller is the owner or an admin, so may rename and remove it, and set its slots. */
  mayChange: boolean;
  /**
   * The project's Tasks, Code review and CI (#2669), one per slot: every folder in the project uses
   * them. A slot that is not here is each folder's own.
   */
  slots?: ProjectSlot[];
}

/** A folder in a project (#2317), as its machine last reported it. */
export interface ProjectFolder {
  machine: MachineRef;
  folder: URLString;
  name: string;
}

/** projects/list (#2317): the organisation's projects, by name. */
export interface ProjectList {
  projects: Project[];
}

/** projects/remove (#2317): the project. Refused while a folder names it. */
export interface ProjectRequest {
  id: string;
}

/** projects/set (#2317): makes a project, or with id renames one. */
export interface ProjectSet {
  id?: string;
  name: string;
}

/**
 * A project's Tasks, Code review or CI slot (#2669): the forge and the repository (GitHub
 * owner/name, GitLab group/project) that fill it for every folder in the project, or skipped.
 */
export interface ProjectSlot {
  slot: ConnectorSlotKind;
  forge?: ConnectionProvider;
  repository?: string;
  /** The repository's host: github.com, gitlab.com, or a self-managed GitLab's host. */
  site?: string;
  /** Skipped for every folder in the project. forge, repository and site are then absent. */
  skipped?: boolean;
}

/**
 * projects/setSlot (#2669): sets one of the project's slots, or with no value gives it back to each
 * folder. Only the owner or an admin.
 */
export interface ProjectSlotSet {
  id: string;
  slot: ConnectorSlotKind;
  value?: ProjectSlot;
}

/** One project's slots, as a machine gets them (#2669). */
export interface ProjectTools {
  id: string;
  name: string;
  slots: ProjectSlot[];
}

/**
 * control/projectsChanged (#2317): a project was made, renamed, adopted or removed, or a folder
 * joined one.
 */
export interface ProjectsChanged {
  id?: string;
  removed?: boolean;
}

/**
 * projects/joined (#2317): a machine's folders and the project each names, all of them each time.
 */
export interface ProjectsJoined {
  folders: JoinedFolder[];
}

export type PromptOrigin =
  | "person"
  | "app"
  | "agent";

export interface PromptRequest {
  agentID: UUID;
  text: string;
  attachments: Attachment[];
  from: PromptOrigin;
  sendID?: UUID;
  /**
   * Sent from voice mode (#2322): the daemon puts the voice-mode text in front of the words, as the
   * prompt's preface.
   */
  voice?: boolean;
}

/**
 * providers/add and providers/update. `secrets` only ever goes to the control plane; `cli` is not
 * kept; `draft` is the draft this accepts (#858).
 */
export interface ProviderAdd {
  id?: ProviderID;
  name: string;
  kind: "commands" | "stdio" | "http";
  command?: string;
  args?: string[];
  url?: string;
  headers?: Record<string, string>;
  commands?: JSONValue;
  map?: JSONValue;
  secrets?: Record<string, string>;
  cli?: string;
  draft?: UUID;
}

/** providers/create. */
export interface ProviderCreate {
  id: ProviderID;
  name: string;
  options?: JSONValue;
  clones?: string[];
  /**
   * The repository to start it from (#1809), an https git address. A provider whose New Machine
   * form has `repository`, such as Codespaces, makes the workspace from it; any other has the host
   * clone it once it joins, before `clones`.
   */
  repository?: string;
}

/** What providers/create made. */
