/**
 * readApi/list (#2019), an admin's: the read API's tokens, newest first, revoked ones too; its URL;
 * and the OTLP exporter when one is set.
 */
export interface ReadAPI {
  tokens: ReadToken[];
  url: string;
  otlp?: OTLPExport;
}

/**
 * A read API token (#2019, #1804 decision 4), with no value: the control plane keeps only its
 * SHA-256. It reads the organisation's reports at /v1/read/reports, and nothing else.
 */
export interface ReadToken {
  id: string;
  name: string;
  made: OrgRouteStamp;
  lastUse?: SCIMTokenUse;
  revoked?: OrgRouteStamp;
}

/** readApi/make (#2019): the token, its value once (never shown again), and the URL to read. */
export interface ReadTokenMade {
  token: ReadToken;
  value: string;
  url: string;
}

/** readApi/make (#2019): a name for the token, such as the BI tool that uses it. */
export interface ReadTokenMake {
  name: string;
}

/** readApi/revoke (#2019): the token to stop at once. */
export interface ReadTokenRevoke {
  id: string;
}

/**
 * Makes or brings up to date a host's copy of a Mac's repository (#1123): fetches the `bundle`
 * upload, moves `branches` forward only, checks out `checkout`, sets `origin`, applies the `patch`
 * upload (uncommitted changes), and adds the folder as a folder. It stops, and changes nothing,
 * when the host has changes or commits of its own.
 */
export interface ReceiveRequest {
  folder: string;
  bundle?: UUID;
  patch?: UUID;
  branches: SentBranch[];
  checkout: string;
  origin?: string;
}

/**
 * What a host has at a folder before a send (#1123). `heads` are the commits of its branches, so
 * the Mac's bundle carries only what the host lacks. `ownChanges` is true when the folder has
 * changes that the last send did not put there.
 */
export interface ReceiveState {
  folder: URLString;
  exists: boolean;
  repository: boolean;
  ownChanges: boolean;
  heads: string[];
}

/**
 * Asks a host about a folder a Mac will send a repository to (Send to ‹host›…, #1123). `folder` may
 * start with ~/.
 */
export interface ReceiveStateRequest {
  folder: string;
}

/**
 * One part of a file a Mac sends (#1123), at `offset` in the upload. A part is at most 16 MB; the
 * host keeps the upload until folders/receive uses it.
 */
export interface ReceiveUploadRequest {
  upload: UUID;
  offset: number;
  data: Base64;
}

/** relay/count (#1163): one device's Needs you count, posted as a silent push. */
export interface RelayCount {
  device: UUID;
  waiting: number;
  countedAt: WireDate;
}

/**
 * relay/deliver (T097): seal the headline to `publicKey` and post it for `device`; no headline is a
 * withdrawal.
 */
export interface RelayDelivery {
  needID: NeedID;
  device: UUID;
  publicKey?: Base64;
  headline?: Headline;
  alert: boolean;
  waiting?: number;
}

/** A device a relay host may carry for, with the key its frames are sealed to. */
export interface RelayDevice {
  id: UUID;
  publicKey: Base64;
}

/** relay/devices: every device client. */
